custom_css:
/* 拟态播放器(紫藤花版) 2026-1-2
   作者：咩野(DC@lambkinling)
   感谢: 部分代码来自kakaa老师的双色盒子 、nakari
   请勿二传二改，倒卖&商用引流司马 */

:root {
  --border-radius-small: 5px;
  --color-1: #d1c4e9;
  --color-2: #f8f3ff;
  --color-3: rgba(248, 235, 250, 1);
  --color-4: #fcf5fd;
  --quote: color-mix(in srgb, var(--SmartThemeUnderlineColor) 50%, #fff);
  --模糊程度: 3px;
  --shadow:
    inset 1px 1px 3px rgba(255, 255, 255, 0.95),
    1px 1px 3px rgba(0, 0, 0, 0.12),
    -1px -1px 2px rgba(255, 255, 255, 0.75),
    inset -2px -2px 4px #fff;
}

body * {
  box-shadow: none !important;
  filter: none !important;
  -webkit-filter: none !important;
}

/* ========== 滚/滑动条 ========== */
/* 滚动条 */
::-webkit-scrollbar {
  display: none;
}

html {
  scrollbar-width: thin;
  scrollbar-color: var(--color-1) transparent;
}

body {
  -webkit-overflow-scrolling: touch;
}

/* 滑动条 */
input[type="range"] {
  background: color-mix(in srgb, var(--color-4) 20%, #fff) !important;
  box-shadow:
    inset 2px 1px 1px rgba(255, 255, 255, 0.2),
    inset 0 0 3px var(--color-1) !important;
}

input[type="range"]::-webkit-slider-thumb {
  background: var(--color-1);
  border-radius: var(--border-radius-small);
  border: none;
  outline: none;
  transform: scale(0.8);
  box-shadow: var(--shadow) !important;
}

/* ========== 文本样式 ========== */
/* 对话 */
q {
  background: linear-gradient(to top, var(--quote) 45%, transparent 40%);
  padding: 0 2px;
  background-repeat: no-repeat;
  background-position: 0 50%;
  background-size: 100% 1em;
}

/* 斜体 */
em {
  text-decoration: underline;
  text-decoration-style: dotted;
  text-underline-offset: 0.15em;
}

del {
  color: crimson;
}

code {
  background: linear-gradient(to right bottom, var(--color-3), var(--color-2), #fff) !important;
  color: var(--SmartThemeBodyColor) !important;
  border: none;
  box-shadow: 
    -1px -1px 2px rgba(255, 255, 255, 0.95),
    inset 1px 1px 1px rgba(0, 0, 0, 0.1),
    1px 1px 2px rgba(0, 0, 0, 0.1),
    inset -1px -1px 2px rgba(255, 255, 255, 0.55) !important;
}

pre code {
  background: linear-gradient(to right bottom, var(--color-1) 0%, var(--color-2) 95%, #fff 100%) !important;
  box-shadow: 
    inset 1px 1px 3px rgba(255, 255, 255, 0.9),
    2px 2px 2px rgba(0, 0, 0, 0.12),
    inset -2px -2px 5px #fff !important;
}

/* md引用文本 */
blockquote {
  border-color: var(--SmartThemeUnderlineColor) !important;
  background: linear-gradient(to right, var(--quote), transparent) !important;
}

/* ========== 聊天区域 ========== */
/* --- 欢迎页 --- */
.welcomePanel {
  background: none !important;
  border: none !important;
}

.welcomePanel .recentChatList .recentChat {
  margin-bottom: 10px;
  border-radius: var(--border-radius-small);
  background: linear-gradient(to right bottom, var(--color-1) 0%, var(--color-2) 50%, var(--color-4) 85%, #fff 100%) !important;
  border: none !important;
  box-shadow: 
    inset 1px 1px 3px rgba(255, 255, 255, 0.9),
    2px 2px 2px rgba(0, 0, 0, 0.12),
    inset -2px -2px 5px #fff !important;
}

.chatNameContainer {
  padding: 1px 3.5px;
}

.mes_button.showRecentChats .fa-circle-chevron-down::before {
  content: "\f0e0";
}

.mes_button.hideRecentChats .fa-circle-xmark::before {
  content: "\f658";
}

.mes_button.hideRecentChats,
.mes_button.showRecentChats {
  opacity: 0.75;
}

/* by nakari */
#form_sheld {
  margin: 0px auto !important;
}

#sheld {
  top: var(--bottomFormBlockSize);
  height: calc(100dvh - var(--bottomFormBlockSize));
  max-height: calc(100dvh - var(--bottomFormBlockSize));
}

#chat {
  background: transparent;
  border: none;
}

/* 最后一条消息 */
.last_mes .mesAvatarWrapper {
  padding-bottom: 0 !important;
}

.last_mes {
  margin-bottom: 20px !important;
}

.last_mes .mes_block {
  padding-bottom: 45px !important;
}

/* ----- 气泡框 ----- */
.mes {
  position: relative;
  overflow: visible;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: calc(100% - 10px); /* 宽度 */
  background: transparent;
  padding: 0;
  margin: 20px auto;
}

/* 文本框 */
body .mes_block {
  display: flex;
  flex-direction: column;
  gap: 0;
  overflow: visible;
  -webkit-backdrop-filter: blur(var(--模糊程度)) !important;
  backdrop-filter: blur(var(--模糊程度)) !important;
  border-radius: 7px;
  padding: 5px 10px;
  background: linear-gradient(to right bottom, var(--color-1), var(--color-2) 80%, var(--color-3), #fff);
  box-shadow: var(--shadow) !important;
}

/* 文本 */
.mes_text {
   padding: 0;
   text-align: justify;
}

.mes_text p:empty {
    display: none;
}

.mes[is_user="true"] .mes_text {
  padding-top: 5px;
}

.mes[is_user="true"] p:last-child {
    margin-bottom: 0;
}

/* --- 小铅笔 --- */
/* 置底 */
.mes .ch_name {
  order: 1;
  line-height: 1;
}

.mes_button,
.mes_edit_buttons {
  font-size: 0.75em;
  opacity: 1 !important;
  color: var(--color-1) !important;
  filter: none !important;
  text-shadow: 
    0.8px 0.8px 0 #fff,
    1px 1px 0 var(--color-1),
    1.1px 1.1px 0 var(--color-1),
    1.5px 1.2px 0 var(--color-1) !important;
  gap: 0;
  visibility: hidden;
}

.mes .menu_button {
  opacity: 1; 
  transform: scale(0.85);
}

.mes_button.hideRecentChats,
.mes_button.showRecentChats {
  visibility: visible;
}

.mes_block:hover .mes_button,
.mes_block:hover .mes_edit_buttons {
  visibility: visible;
}

/* --- 左右箭头 --- */
.swipe_right,
.swipe_left {
  opacity: 1;
  border-radius: 50%;
  font-size: 0.9em;
  background: linear-gradient(var(--color-2), var(--color-4));
  box-shadow: var(--shadow) !important;
  &::before {
    content: "\f051";
    color: var(--color-1);
  }
}

.swipe_left {
  display: flex;
  justify-content: center;
  align-items: center;
  &::before {
    content: "\f048";
  }
 }

.swipes-counter {
  transform: translateY(3px);
  color: var(--color-1);
}

/* by KAKAA */
.swipeRightBlock {
  flex-direction: row-reverse;
  bottom: calc(var(--swipeCounterHeight) + var(--swipeCounterMargin));
  margin-right: 15px;
}

.swipeRightBlock:not(.last_mes .swipeRightBlock) {
   pointer-events: none;
}

/* ----- 头像区域 ----- */
body .mesAvatarWrapper {
  align-self: flex-start;
  display: flex;
  overflow: hidden;
  position: relative;
  align-items: center;
  aspect-ratio: 23/10; 
  width: 100%;
  max-width: 400px;
  height: auto;
  -webkit-backdrop-filter: blur(var(--模糊程度)) !important;
  backdrop-filter: blur(var(--模糊程度)) !important;
  border-radius: 7px;
  margin-bottom: 5px;
  gap: 22px; /* 楼层计时器等间距 */
  background: linear-gradient(to right bottom, var(--color-1), var(--color-2) 85%, #fff);
  box-shadow: var(--shadow) !important;
}

/* 📌播放器(改色) */
.mesAvatarWrapper::before {
  content: "";
  position: absolute;
  right: 5px;
  bottom: 30px;
  width: 55%;
  height: auto;
  aspect-ratio: 1082 / 418;
  background-image: url('https://i.postimg.cc/4x22tXYb/41-20250824060746.png');
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  opacity: 0.9;
  filter: hue-rotate(290deg); /* 调色 , 0-360 */
}

/* 头像 */
.mes .avatar {
  display: flex;
  aspect-ratio: 1/1; 
  width: auto !important;
  height: 100%;
  flex: 0 0 auto;
  padding: 5px; /* 头像边距 */
}

.mesAvatarWrapper .avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* 楼层、计时器、tokens */
.mesIDDisplay:empty,
.mes_timer:empty,
.tokenCounterDisplay:empty {
  display: none;
}

.mesIDDisplay,
.mes_timer,
.tokenCounterDisplay {
  transform: translateY(52px) scale(0.8); /* 位置、大小 */
}

/* --- 📌名字 --- */
.mes .name_text {
  overflow: visible;
  position: absolute;
  top: -135px; /* 名字上下 */
  left: 145px;
  font-size: 1.2rem; /* 歌名&名字字体大小 */
  color: var(--SmartThemeBodyColor);
  white-space: nowrap;
}

/* 自定义歌名 - User */
.mes .name_text::before {
  content: "《I Lover U》- ";
}

/* 歌名 - Char */
div[is_user="false"] .mes .name_text::before {
  content: "《I Lover U 2》- ";
}

/* 时间戳 */
.mes .timestamp {
  position: absolute;
  bottom: 5px;
  left: 50%;
  transform: translateX(-50%);
  white-space: nowrap;
  font-size: 0.5rem; /* 大小 */
  &::before, &::after {
    content: " - ";
  }
}

/* --- 📌思维链 --- */
.mes_reasoning_header {
  border-radius: var(--border-radius-small);
  background: linear-gradient(135deg, var(--color-1), var(--color-3), var(--color-2)) !important;
  box-shadow:  var(--shadow) !important;
}

/* 文案更替 */
.mes_reasoning_header_title::before {
  content: "ıllıllıı歌曲列表";
  font-size: calc(var(--mainFontSize) * 0.9);
}

.mes_reasoning_header_title {
  font-size: 0;
}

@media (max-width: 768px) {
  .mes_reasoning_details {
    position: relative;
}
  .mes_reasoning_details[open] {
  width: 100%;
}
  .mes_reasoning {
    width: 100%;
    max-height: 500px; /* 内容高度 */
    overflow: hidden auto;
    font-size: calc(var(--mainFontSize) * 0.9);
    border-radius: 8px;
    border: none;
    background: color-mix(in srgb, var(--SmartThemeUnderlineColor) 15%, #fff);
    box-shadow:
      inset 1px 1px 2px rgba(0, 0, 0, 0.15),
      inset -1px -1px 2px rgba(255, 255, 255) !important;
  }
  .mes_reasoning_actions {
     position: absolute;
     right: 5px;
     top: 5px;
     z-index: 10;
     flex-shrink: 0;
     padding: 0 5px;
  }
}

/* ========== 抽屉菜单 ========== */
/* 全局头像 */
.avatar img,
body.big-avatar .avatar img{
  border: none;
}

/* by @Junezz */
body.square-avatars .avatar:not(.mes .avatar),
body.square-avatars .avatar:not(.mes .avatar) img {
    border-radius: 50% !important;
}

/* 头像框 */
.avatar:not(.mes .avatar) {
  position: relative;
  &::before {
    content: "";
    position: absolute;
    aspect-ratio: 1 / 1;
    width: 150%;
    top: 58%;
    left: 50%;
    transform: translate(-50%, -50%);
    background: url("https://files.catbox.moe/wcv082.png");
    background-size: 100%
  }
}

#rm_button_characters {
  font-size: calc(var(--mainFontSize) * 1.2);
}

.reverse_proxy_warning {
  background-color: transparent !important;
}

#movingUIPresets{
  margin-top: 2px;
  margin-bottom: 0 !important;
}

/* --- 抽屉背景 --- */
body .drawer-content {
  box-shadow: none !important;
  border-radius: 0 0 var(--border-radius-small) var(--border-radius-small);
  border: none;
  border-bottom: 1px solid var(--color-1);
}

/* --- 标题栏 --- */
.standoutHeader,
.inline-drawer-header,
#theme-manager-header,
#extensions_settings .inline-drawer-toggle.inline-drawer-header, 
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4:not(#theme-manager-header h4),
#top-settings-holder h4:not(#ai-config-button):not(#rightNavHolder):not(#theme-manager-header h4)  {
  background: 
    linear-gradient(to right bottom, 
    var(--color-1) 0%, 
    var(--color-2) 75%, 
    #fff 100%);
  border-radius: var(--border-radius-small);
  border: none;
  box-shadow: var(--shadow) !important;
  margin-bottom: 5px;
  padding: 2px 3px 2px 8px;
}

/* 箭头 */
.inline-drawer-icon {
  color: var(--color-1);
  filter: drop-shadow(0 0 12px var(--SmartThemeBorderColor));
  opacity: 0.75;
  font-size: 1.3em;
  margin: 2px;
}

.inline-drawer-icon::before {
  content: "\✿" !important;
}

.inline-drawer-icon.up::before {
  content: "\❀" !important;
}

/* --- 按钮 --- */
.mes .menu_button,
.menu_button:not(.mes_edit_buttons *) {
  background: 
    linear-gradient(to right bottom, 
    var(--color-3), 
    var(--color-2), 
    #fff);
  color: var(--color-1);
  border: none;
  border-radius: var(--border-radius-small);
  box-shadow: var(--shadow) !important;
}

#delete_button,
#dialogue_del_mes_ok,
#dialogue_popup_ok,
#bulk_tag_popup_reset,
#bulk_tag_popup_remove_mutual,
#persona_delete_button,
#world_popup_delete,
.mes_edit_cancel.menu_button,
.menu_button.popup-button-ok,
.redWarningBG {
  background: crimson !important;
  color: black !important;
}

.qr--button {
  border: none !important;
  border-radius: var(--border-radius-small) !important;
}

/* --- 勾选框 --- */
input[type="checkbox"] {
  background: linear-gradient(to right, var(--color-3), var(--color-2));
  outline: none;
  border-radius: 50%;
  border: none;
  box-shadow: 
   inset 1px 1px 2px rgba(255, 255, 255, 0.9),
   2px 2px 2px rgba(0, 0, 0, 0.1),
   inset -2px -2px 2px #fff,
   -1px -1px 2px #fcf5fd !important;
}

.checkbox_label {
  display: flex;
  align-items: center;
}

input[type="checkbox"]:checked {
  background: var(--color-1) !important;
  &::before {
    content: none;
  }
}

/* --- 下拉框 --- */
#character_sort_order,
select.text_pole,
select {
  background: 
    url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20"><path fill="%23d1c4e9" d="M5.5 7l4.5 4.5 4.5-4.5 1.5 1.5-6 6-6-6z"/></svg>')
        right 4px center / 16px no-repeat,
    linear-gradient(135deg,
        var(--color-3) 0%,
        var(--color-4) 20%,
        var(--color-2) 100%);
  border: none !important;
  outline: none !important;
  box-shadow: var(--shadow) !important;
}

#tag_import_setting {
  margin-top: 5px;
}

/* --- 输入框 --- */
#settingsSearch.textarea_compact,
.text_pole:not(.objective-task):not(select),
input[type="text"],
input[type="number"],
input[type="switch"],
input:not([type]),
textarea:not([type="search"]){
  background: rgba(255, 255, 255, 0.5);
  border: none;
  outline: none !important;
  box-shadow: var(--shadow) !important;
}

input[type="number"] {
  background: 
   linear-gradient(to right bottom,
   var(--color-4),
   var(--color-2),
   #fff);
  box-shadow: var(--shadow) !important;
}

/* --- 弹窗 --- */
#character_popup, 
#dialogue_popup,
.draggable,        
#select_chat_popup, 
.popup:not(.transparent_dialogue_popup) {  
  border-radius: var(--border-radius-small);
  border: none;
  box-shadow:
    1px 1px 5px rgba(255, 255, 255, 0.9),
    0 0 5px var(--color-1) !important;
}

#dialogue_popup_text {
  padding-right: 10px;
}

.popup-content:has(#showRawPrompt) {
  overflow-y: auto;
}

/* 通知提示框 */
div.toast.toast-success {
  background-color: rgba(209, 196, 233, 0.35) !important;
  -webkit-backdrop-filter: blur(10px) !important;
  backdrop-filter: blur(10px) !important;
  border-radius: var(--border-radius-small) !important;
  border: 1px solid var(--color-2);
  color: var(--SmartThemeBodyColor) !important;
  box-shadow:
    1px 1px 5px rgba(255, 255, 255, 0.9),
    0 0 5px var(--color-1) !important;
}

/* --- 预设页 --- */
.range-block-title {
  text-align: left;
}

label[for="openai_image_inlining"] + div, 
#openai_settings .inline-drawer-header .flex-container {
  gap: 0px 1px;
  text-align: left;
}

/* --- 提示词管理器 --- */
#completion_prompt_manager .completion_prompt_manager_header {
    color: var(--SmartThemeBodyColor) !important;
}

#completion_prompt_manager .completion_prompt_manager_header_advanced span,
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt
span
span
span {
    filter: none !important;
}

/* 预设词条目 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
  border-radius: var(--border-radius-small);
  border: none;
  background: var(--color-2);
  box-shadow: var(--shadow) !important;
}

/* 未启用条目 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt_disabled {
  background: transparent;
  box-shadow: none !important;
}

/* 未启用条目的字体颜色 */
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action, #completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt .completion_prompt_manager_prompt_name .fa-solid {
  color: var(--SmartThemeEmColor);
}

#completion_prompt_manager_list {
  padding: 10px;
}

/* ----- 世界书 ----- */
.world_entry {
  margin-top: 10px;
  background: transparent;
}

.wi-card-entry {
  border: none;
}

/* 单击展开 */
#wiTopBlock .inline-drawer.wide100p .inline-drawer-content {
  background: color-mix(in srgb, var(--SmartThemeUnderlineColor) 15%, #fff); !important;
  margin-top: 5px;
  border-radius: var(--border-radius-small);
  border: none;
  box-shadow: var(--shadow) !important;
}

/* ----- 用户设置页 ----- */
/* 刷新回复按钮 */
@media screen and (max-width: 768px) {
  div[name="ChatMessageHandlingToggles"] .checkbox-container.flex-container {
    flex-direction: column;
    align-items: flex-start;
    gap: 0;
    margin: 0 4px 0;
  }

  div[name="ChatMessageHandlingToggles"] .checkbox-container.flex-container input[type="checkbox"] {
    aspect-ratio: 1/1;
    width: 1em;
    height: auto;
  }
}

/* --- 图库 --- */
.bg_example {
    outline: none;
    border: none;
    box-shadow: 0 0 3px var(--color-1) !important;
}

.BGSampleTitle {
    background: none !important;
}

.mobile-only-menu-toggle {
    border-radius: 50% !important;
}

.mobile-only-menu-toggle,
.jg-menu {
    background: var(--color-1) !important;
    transform: scale(0.75) !important;
    opacity: 0.5;
}

.bg_example.selected-background {
    outline: 1.5px dashed var(--color-1);
}

/* 限制正则拖拽触发区域 - 仅移动端和平板 */
@media (hover: none) and (pointer: coarse) {
    .regex-script-label {
        pointer-events: none;
    }
    .regex-script-label > *:not(.regex_script_name) {
        pointer-events: auto;
    }

    .regex-script-label .drag-handle {
        pointer-events: auto;
        padding: 6px 10px; /* 调整把手大小 */
    }
}

.regex-script-label {
  border-radius: var(--border-radius-small) !important;
  border: none !important;
  box-shadow: var(--shadow) !important;
  background: linear-gradient(135deg, var(--color-2), rgba(255, 255, 255, 0.5) 75%);
}

.regex-script-label:has(.disable_regex:checked) {
  background: none !important;
  box-shadow: none !important;
}

.regex_script_name {
  white-space: normal;
}

.regex-script-label.flex-container {
  align-items: center;
}

.regex-toggle-on {
  color: var(--color-1);
}

/* 拓展页输入助手 */
.integrated-button-row {
  margin-bottom: 3px;
  background: var(--color-4) !important;
  border-radius: var(--border-radius-small) !important;
  border: none !important;
  box-shadow: var(--shadow) !important;
  padding: 1px 7px!important;
}

.integrated-button-row .button-preview,
.integrated-button-row .shortcut-input,
.integrated-button-row .shortcut-clear-btn,
.integrated-button-row .custom-edit-btn,
.integrated-button-row .custom-edit-btn {
  -webkit-transform: scale(0.8);
  transform: scale(0.8);
  box-shadow: var(--shadow) !important;
  border: none !important;
}

/* --- User & Char管理器 --- */
.character_select,
.avatar-container{
  border: none;
  border-radius: var(--border-radius-small);
  background: rgba(255, 255, 255, 0.5);
  box-shadow:
    inset -2px -3px 5px rgba(255, 255, 255, 0.75),
    inset 3px 3px 5px rgba(255, 255, 255, 0.75),
    1px 1px 3px rgba(0, 0, 0, 0.1) !important;
}

.character_select.is_fav,
.avatar-container.selected {
  background: 
    linear-gradient(to right bottom,
    var(--color-1) 0%,
    var(--color-2) 50%,
    var(--color-4) 75%,
    var(--color-2) 100%);
  outline: none !important;
  border: none !important;
}

/* --- 角色管理器 --- */
.character_select {
  margin-top: calc(var(--mainFontSize) * 0.5);
}

/* 星标 */
.character_select.is_fav .avatar {
  outline: none;
}

.character_select.is_fav .ch_name {
  color: var(--SmartThemeQuoteColor);
}

/* 标签按钮 */
.tag.actionable {
  color: var(--SmartThemeBorderColor);
  font-size: calc(var(--mainFontSize) * 0.95);
  box-shadow: var(--shadow) !important;
  margin-bottom: 2px;
}

/* 收藏区滚动 */
#HotSwapWrapper {
  overflow: hidden;
}

#HotSwapWrapper > div {
  overflow: auto hidden; 
  flex-wrap: nowrap;
  height: calc(var(--avatar-base-height) + 20px);
  max-height: calc(var(--avatar-base-height) * 2.5);
}

#HotSwapWrapper > div::-webkit-scrollbar-thumb {
  background-color: var(--color-1);
}

.avatars_inline {
  flex-wrap: nowrap;
  overflow: visible;
  gap: 7px;
}

/* ========== 顶栏&底栏 ========== */
/* 紫藤花装饰 */
#top-bar::before {
  content: "";
  position: absolute;
  top: 0;
  left: 50%;
  width: 100vw;
  height: calc(100vw * 903 / 1200);
  background: url('https://i.postimg.cc/G3NXRYwC/1726718476457-jpg.png') center top / cover;
  transform: translateX(-50%);
  z-index: -1;
  pointer-events: none;
  filter: hue-rotate(-15deg);
} 

/* 顶栏 & 底栏 */
#top-bar,
body.no-blur #top-bar {
  background: transparent !important;
  outline: none !important;
  border: none !important;
  box-shadow: none !important;
}

#send_form,
body.no-blur #send_form {
  outline: none !important;
  border: none !important;
  padding: 10px 5px 5px;
  border-radius: var(--border-radius-small) var(--border-radius-small) 0 0;
  background: linear-gradient(to bottom, var(--color-1), var(--color-2) 75%, var(--color-4)) !important;
  box-shadow: var(--shadow) !important;
}

/* --- 顶栏图标 --- */
.drawer-icon.fa-fw {
  display: flex;
  overflow: visible;
  justify-content: center;
  opacity: 0.75 !important;
  font-size: calc(var(--mainFontSize) * 1.2);
  text-shadow: none !important;
  color: var(--SmartThemeBorderColor);
}

/* --- 底栏图标 --- */
#quick-reply-rocket-button,
#send_form .fa-solid {
  opacity: 0.85 !important;
  font-size: calc(var(--mainFontSize) * 1.35);
  color: var(--color-1);
}

#options_button::before {
  content: "\f03c";
}

#extensionsMenuButton::before {
  content: "\f025";
}

#send_but::before {
  content: "\f245";
}

#mes_stop i::before {
  content: "\f04c";
  color: crimson;
}

#send_form .fa-solid:hover,
#quick-reply-rocket-button:hover,
.drawer-icon.fa-fw:hover {
  -webkit-transform: translateY(-2px);
  transform: translateY(-2px);
  transition: all 0.2s ease-in-out;
  color: var(--SmartThemeBorderColor);
}

/* --- 底栏输入框 --- */
#send_form textarea {
  background: transparent;
  border: none;
  clip-path: none;
  box-shadow: none !important;
}

#send_textarea::placeholder {
  opacity: 0;
}

#nonQRFormItems {
  position: relative;
  display: flex;
  align-items: center;
}

/* 📍输入框文案 */
#nonQRFormItems::before {
  content: "|◁◁ Ⅱ ■ ▷▷|";
  position: absolute;
  left: calc(50% + 10px); /* 左右位置 */
  top: 50%;
  transform: translate(-50%, -50%);
  font-size: 0.75rem;
  color: var(--color-1);
  pointer-events: none;
  z-index: 1;
  padding: 8px 0;
}

#nonQRFormItems:has(#send_textarea:focus)::before,
#nonQRFormItems:has(#send_textarea:not(:placeholder-shown))::before {
  display: none !important;
}

#select_chat_popup,
.list-group,
#extensionsMenu,
#options,
body .drawer-content,
body .popup {
  -webkit-backdrop-filter: blur(var(--模糊程度)) !important;
  backdrop-filter: blur(var(--模糊程度)) !important;
}

/* 隐藏qr (测试中)*/
#qr--bar {
  display: none !important;
}

#send_form:focus-within #qr--bar {
  display: flex !important;
}

/* 加载消息 */
#show_more_messages {
  font-size: 0;
  background-color: #f5f5f5;
  padding: 2px 8px;
  outline: none;
  border-radius: 5px;
  box-shadow:
    0 0 2.5px var(--color-1),
    1px 1px 5px var(--color-3),
    inset 0 0 5px #fff !important;
  background: linear-gradient(to right bottom, var(--color-3), var(--color-2) 60%, var(--color-4), #fff);
  line-height: 1.6;
}

#show_more_messages::after {
  content: "₊⋆♡₊˚ 𝓣𝓱𝓮𝓻𝓮 𝓲𝓼 𝓷𝓮𝓿𝓮𝓻 𝓪 𝓯𝓲𝓷𝓪𝓵 𝓬𝓱𝓪𝓹𝓽𝓮𝓻 ˚₊♡⋆₊\A- 永远没有完结篇 -";
  white-space: pre;
  color: var(--SmartThemeEmColor);
  font-style: italic;
  font-size: calc(var(--mainFontSize) * 0.8);
}
